{\bf Proof of Part 5.} Because $A_{(\nu)}$ is trained jointly with $W_{(\nu)},U_{(\nu)}$ by gradient flow (Section~\ref{sec:preli}), the entries $a_{(\nu),r,k}(t)$ are no longer in $\{-1,+1\}$ for $t>0$ and are in general not independent of $w_{(\nu),r}(t)$. We therefore prove Part~5 in two steps: first at the initialization time $t=0$ via Hoeffding (where the i.i.d.\ $\pm 1$ assumption holds), then for $t>0$ via the perturbation bound of Part~13 of this lemma and the FFN-drift bound of Lemma~\ref{lem:ffn_drift}.

    {\it Step 1: $\nu=1$ at $t=0$.} The data assumption (Section~\ref{sub:setups}) gives $\|\Lambda_{(0), i, \ell}\|_2 = \|X_{i,\ell}+E_\ell\|_2 = \Theta(1)$ for every $\ell$. Combined with the fact that $\sigma_{(1), p}(0)$ is a probability vector,
    \begin{align*}
        \|o_{(1), p}(0)\|_2 = \|\Lambda_{(0), i}(0)^\top \sigma_{(1), p}(0)\|_2 \le \max_{\ell'} \|\Lambda_{(0), i, \ell'}\|_2 = \Theta(1).
    \end{align*}
    For the $\mu$-term at $t=0$, we note that $a_{(1),r,k}(0) \in \{-1,+1\}$ is i.i.d.\ uniform and independent of $w_{(1),r}(0)\sim\mathcal{N}(0,I_d)$ (the i.i.d.\ initialization ensures this). Hence, fixing $k\in[d]$ and conditioning on $w_{(1),r}(0)$:
    \begin{align*}
        |a_{(1), r, k}(0)\cdot\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)| & ~ \le 1\cdot\|w_{(1),r}(0)\|_2\cdot\|o_{(1),p}(0)\|_2 \le O(\sqrt{d}B), \\
        {\mathbb{E}}\big[a_{(1), r, k}(0)\cdot\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)\,\big|\, w_{(1),r}(0)\big] & ~ = {\mathbb{E}}[a_{(1),r,k}(0)]\cdot \phi(\cdot) = 0.
    \end{align*}
    By Hoeffding (Lemma~\ref{lem:hoeffding}) applied to $\sum_{r=1}^m a_{(1),r,k}(0)\phi(\langle o_{(1),p}(0),w_{(1),r}(0)\rangle)$, with probability at least $1-\delta/(md)$:
    \begin{align*}
        \Big|\sum_{r=1}^m a_{(1), r, k}(0)\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)\Big| \le O(\sqrt{md}B)\sqrt{\log(md/\delta)} \le O(\sqrt{m}\,\sqrt{d}\,B^2).
    \end{align*}
    Taking the union bound over $k\in[d]$:
    \begin{align*}
        \|\mu_{(1), p}(0)\|_2 \le \frac{\omega\sqrt d}{\sqrt m}\max_{k\in[d]}\Big|\sum_r a_{(1),r,k}(0)\phi(\cdot)\Big| \le O(\omega\, d\, B^2),
    \end{align*}
    and therefore
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(0)\|_2 \le \|\Lambda_{(0), i, \ell}(0)\|_2 + \|\mu_{(1), p}(0)\|_2 \le \Theta(1) + O(\omega d B^2) = \Theta(1)\pm o(1/N),
    \end{align*}
    where the last step uses $\omega = o(1/(NdB^2))$ from Definition~\ref{def:gd}.

    {\it Step 2: Extension from $t=0$ to $t>0$.} By Parts~9, 10 and~13 of this lemma (proven below), $\|w_{(1),r}(t)-w_{(1),r}(0)\|_2 \le R$ and $\|o_{(1),p}(t)-o_{(1),p}(0)\|_2 \le O(\sqrt L R)$. By Lemma~\ref{lem:ffn_drift}, $\|A_{(\nu)}(t) - A_{(\nu)}(0)\|_F \le R_A := O(1/(\sqrt m\,\omega\lambda N))$. The Lipschitz expansion of the layer-1 hidden state with respect to $(W,A,o)$ then gives:
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(t) - \Lambda_{(1), i, \ell}(0)\|_2 &\le \frac{\omega}{\sqrt m}\,\Big( \|A_{(1)}(t) - A_{(1)}(0)\|_F\cdot \max_r |\phi(\langle w_{(1),r}(t),o_{(1),p}(t)\rangle)| \\
        &\quad+ \|A_{(1)}(0)\|_F\cdot \big[\max_r \|w_{(1),r}(t)-w_{(1),r}(0)\|_2\cdot \|o_{(1),p}(t)\|_2 + \cdots\big]\Big) \\
        &\le \frac{\omega}{\sqrt m}\big( R_A\cdot O(\sqrt d B) + O(\sqrt{md})\cdot O(R) \big) \\
        &= O\Big(\frac{\omega\sqrt d B}{\sqrt m\,\omega\lambda N}\Big) + O(\omega\sqrt d\, R) = o(1)
    \end{align*}
    under the strengthened width condition of Lemma~\ref{lem:ffn_drift}. Combining with Step~1:
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(t)\|_2 \le \|\Lambda_{(1), i, \ell}(0)\|_2 + o(1) = \Theta(1).
    \end{align*}

    {\it Step 3: Inductive step ($\nu \ge 2$).} Assume the bound holds for layer $\nu-1$. Then $\|\Lambda_{(\nu-1),i,\ell}(t)\|_2 = \Theta(1)$ uniformly in $\ell$ and $t$, hence $\|o_{(\nu),p}(t)\|_2 = \|\Lambda_{(\nu-1),i}(t)^\top\sigma_{(\nu),p}(t)\|_2 \le \max_{\ell'}\|\Lambda_{(\nu-1),i,\ell'}(t)\|_2 = \Theta(1)$. The Hoeffding-then-perturb argument of Steps~1 and~2 applies verbatim to $\mu_{(\nu),p}$ (with all quantities re-indexed to layer $\nu$), giving $\|\Lambda_{(\nu),i,\ell}(t)\|_2 = \Theta(1)$ as claimed. The bound on $\|o_{(\nu),p}(t)\|_2$ follows directly:
    \begin{align} \|o_{(\nu), p}(t)\|_2 = \Theta(1).
    \end{align}

{\it Step 1: $\nu=1$ at $t=0$.} The data assumption (Section~\ref{sub:setups}) gives $\|\Lambda_{(0), i, \ell}\|_2 = \|X_{i,\ell}+E_\ell\|_2 = \Theta(1)$ for every $\ell$. Combined with the fact that $\sigma_{(1), p}(0)$ is a probability vector,
    \begin{align*}
        \|o_{(1), p}(0)\|_2 = \|\Lambda_{(0), i}(0)^\top \sigma_{(1), p}(0)\|_2 \le \max_{\ell'} \|\Lambda_{(0), i, \ell'}\|_2 = \Theta(1).
    \end{align*}
    For the $\mu$-term at $t=0$, we note that $a_{(1),r,k}(0) \in \{-1,+1\}$ is i.i.d.\ uniform and independent of $w_{(1),r}(0)\sim\mathcal{N}(0,I_d)$ (the i.i.d.\ initialization ensures this). Hence, fixing $k\in[d]$ and conditioning on $w_{(1),r}(0)$:
    \begin{align*}
        |a_{(1), r, k}(0)\cdot\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)| & ~ \le 1\cdot\|w_{(1),r}(0)\|_2\cdot\|o_{(1),p}(0)\|_2 \le O(\sqrt{d}B), \\
        {\mathbb{E}}\big[a_{(1), r, k}(0)\cdot\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)\,\big|\, w_{(1),r}(0)\big] & ~ = {\mathbb{E}}[a_{(1),r,k}(0)]\cdot \phi(\cdot) = 0.
    \end{align*}
    By Hoeffding (Lemma~\ref{lem:hoeffding}) applied to $\sum_{r=1}^m a_{(1),r,k}(0)\phi(\langle o_{(1),p}(0),w_{(1),r}(0)\rangle)$, with probability at least $1-\delta/(md)$:
    \begin{align*}
        \Big|\sum_{r=1}^m a_{(1), r, k}(0)\phi(\langle o_{(1), p}(0), w_{(1), r}(0)\rangle)\Big| \le O(\sqrt{md}B)\sqrt{\log(md/\delta)} \le O(\sqrt{m}\,\sqrt{d}\,B^2).
    \end{align*}
    Taking the union bound over $k\in[d]$:
    \begin{align*}
        \|\mu_{(1), p}(0)\|_2 \le \frac{\omega\sqrt d}{\sqrt m}\max_{k\in[d]}\Big|\sum_r a_{(1),r,k}(0)\phi(\cdot)\Big| \le O(\omega\, d\, B^2),
    \end{align*}
    and therefore
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(0)\|_2 \le \|\Lambda_{(0), i, \ell}(0)\|_2 + \|\mu_{(1), p}(0)\|_2 \le \Theta(1) + O(\omega d B^2) = \Theta(1)\pm o(1/N),
    \end{align*}
    where the last step uses $\omega = o(1/(NdB^2))$ from Definition~\ref{def:gd}.

{\it Step 2: Extension from $t=0$ to $t>0$.} By Parts~9, 10 and~13 of this lemma (proven below), $\|w_{(1),r}(t)-w_{(1),r}(0)\|_2 \le R$ and $\|o_{(1),p}(t)-o_{(1),p}(0)\|_2 \le O(\sqrt L R)$. By Lemma~\ref{lem:ffn_drift}, $\|A_{(\nu)}(t) - A_{(\nu)}(0)\|_F \le R_A := O(1/(\sqrt m\,\omega\lambda N))$. The Lipschitz expansion of the layer-1 hidden state with respect to $(W,A,o)$ then gives:
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(t) - \Lambda_{(1), i, \ell}(0)\|_2 &\le \frac{\omega}{\sqrt m}\,\Big( \|A_{(1)}(t) - A_{(1)}(0)\|_F\cdot \max_r |\phi(\langle w_{(1),r}(t),o_{(1),p}(t)\rangle)| \\
        &\quad+ \|A_{(1)}(0)\|_F\cdot \big[\max_r \|w_{(1),r}(t)-w_{(1),r}(0)\|_2\cdot \|o_{(1),p}(t)\|_2 + \cdots\big]\Big) \\
        &\le \frac{\omega}{\sqrt m}\big( R_A\cdot O(\sqrt d B) + O(\sqrt{md})\cdot O(R) \big) \\
        &= O\Big(\frac{\omega\sqrt d B}{\sqrt m\,\omega\lambda N}\Big) + O(\omega\sqrt d\, R) = o(1)
    \end{align*}
    under the strengthened width condition of Lemma~\ref{lem:ffn_drift}. Combining with Step~1:
    \begin{align*}
        \|\Lambda_{(1), i, \ell}(t)\|_2 \le \|\Lambda_{(1), i, \ell}(0)\|_2 + o(1) = \Theta(1).
    \end{align*}

{\bf Proof of Part 8.} Following Part 7 of this lemma, we can show that:
    \begin{align*}
        \sum_{\ell'\in [\ell]} \exp(\Lambda_{(\nu), i, \ell}(t)^\top U_{(\nu)}(t) \Lambda_{(\nu), i, \ell'}(t)) \le \ell \exp(O(dB)) \le L \exp(O(dB)).
    \end{align*}

    Then we can show that:
    \begin{align*}
        \sigma_{(\nu), p, \ell'}(t) \ge & ~ \exp(\Lambda_{(\nu), i, \ell}(t)^\top U_{(\nu)}(t) \Lambda_{(\nu), i, \ell'}(t)) / \sum_{\ell'\in [\ell]} \exp(\Lambda_{(\nu), i, \ell}(t)^\top U_{(\nu)}(t) \Lambda_{(\nu), i, \ell'}(t)) \\
        \ge & ~ \frac{\exp(-O(dB))}{L \exp(O(dB))} \\
        \ge & ~ \frac{\exp(-O(dB))}{L}.
    \end{align*}
    Combining the previous results, we obtain the result of this part.

To extend $\|\Lambda_{(2),i,\ell}(t)-\Lambda_{(2),i,\ell}(0)\|_2$ from a $\nu=2$-specific bound to the inductive step, we apply the same two-step argument as in Part~5. At $t=0$, $a_{(2),r,k}(0)\in\{-1,+1\}$ is i.i.d.\ uniform and independent of $w_{(2),r}(0)$, so Hoeffding's inequality (Lemma~\ref{lem:hoeffding}) bounds the i.i.d.\ component as $O(\sqrt{m}\sqrt{d}B^2)$ with high probability; for $t>0$, the difference $\Lambda_{(2),i,\ell}(t)-\Lambda_{(2),i,\ell}(0)$ contains contributions from $w_{(2)}$, $U_{(2)}$, $A_{(2)}$ drift, each bounded by $R$, $R$, $R_A$ respectively (from Parts~9, 10 of this lemma and Lemma~\ref{lem:ffn_drift}). The Lipschitz expansion in $(W, U, A)$ yields:
    \begin{align*}
        \|\Lambda_{(2),i,\ell}(t)-\Lambda_{(2),i,\ell}(0)\|_2 \le O(\sqrt L R) + O(\omega \sqrt d B \cdot R_A) = O(\sqrt L R),
    \end{align*}
    where the second equality uses the strengthened width condition of Lemma~\ref{lem:ffn_drift} so that the $A$-drift term is dominated by the $W,U$-drift.

{\bf Proof of Part 14.}
    We have:
    \begin{align*}
        {\cal L}(t, \mathbb{D}) = & ~ \frac{1}{n} \| {\sf F}(t) - {\sf Y} \|_F^2 \\
        \leq & ~ L\max_{p \in [nL]} \| {\sf F}_p(t) - {\sf Y}_p \|_2^2 \\
        \leq & ~ L\max_{p \in [nL]} \left( \| {\sf F}_p(t)\|_2 +  \| {\sf Y}_p \|_2 \right)^2 \\
        \leq & ~ L \left( O(1) + O(\sqrt{d}) \right)^2 \\
        \leq & ~ O(Ld),
    \end{align*}
    where the first step follows from Lemma~\ref{lem:compact_form_transform}, the second step follows from simple algebras, the third step follows from the Cauchy-Schwartz inequality, the last two steps follow from Definition~\ref{def:D} and simple algebras.

Combine the upper bounds on three terms (after the union bound over $(p,q)\in[nL]^2$, with probability $\ge 1-\delta$), we have:
    \begin{align*}
        | H_{(\nu), p, q}'(t) - H_{(\nu), p, q}'(0) | \leq  O(\sqrt{L}R) \cdot \exp(O(dB)) (nL)^2/\delta.
    \end{align*}

    We have:
    \begin{align} \| H_{(\nu)}'(t) - H_{(\nu)}'(0) \|_F = & ~ \sqrt{\sum_{p=1}^{nL}\sum_{q=1}^{nL} (H_{(\nu), p, q}(t) - H_{(\nu), p, q}(0))^2} \notag \\
        \leq & ~ O(nL^{1.5}R) \cdot \exp(O(dB)) /\delta.
    \end{align}

By Fact~\ref{fac:lambda_min_perturb} ($\lambda_{\min}(\widetilde H) \geq \lambda_{\min}(H) - \|H-\widetilde H\|_F$), Assumption~\ref{ass:positive_definite} ($\lambda_{\min}(H_{(\nu)}'(0)) \ge \omega\lambda$), and choosing
    \begin{align} R \leq \frac{\omega\lambda\delta}{nL^{1.5} \exp(O(dB)) },
    \end{align}
    we obtain $\| H_{(\nu)}'(t) - H_{(\nu)}'(0) \|_F \leq \omega\lambda/4$, which gives:
    \begin{align*}
        \lambda_{\min}(H_{(\nu)}'(t)) \ge \omega\lambda - \omega\lambda/4 = \frac{3}{4} \omega\lambda.
    \end{align*}

It is trivial to have (Part 16 of Lemma~\ref{lem:helpful_bounds}):
    \begin{align*}
        \| \gamma_{(\nu), p}(t) \|_2 \leq o(\frac{1}{\sqrt{m}}).
    \end{align*}

    Therefore, we have:
    \begin{align*}
        | H_{(\nu), p, q}(t) - H_{(\nu), p, q}'(t) |
        = & ~ | \langle \gamma_{(\nu), p}(t), \gamma_{(\nu), q}(t) \rangle | \\
        \leq & ~ o(1/m).
    \end{align*}

    Furthermore, we have:
    \begin{align*}
        \| H_{(\nu)}(t) - H_{(\nu)}'(t) \|_F \leq o(\frac{n}{m}) \leq \omega\lambda/4,
    \end{align*}
    where the last step follows from $m = \Omega(n/(\omega\lambda))$.

Similarly, following Fact~\ref{fac:lambda_min_perturb} and combining the previous result, we have:
    \begin{align*}
        \lambda_{\min}(H_{(\nu)}(t)) \ge \omega \lambda / 2.
    \end{align*}

    Following Fact~\ref{fac:lambda_min_krnocker}, we have:
    \begin{align*}
        \lambda_{\min}(H_{(\nu)}(t) \otimes I_d ) \ge \omega\lambda / 2.
    \end{align*}

{\bf Tighter Bound.} We plug $R = O(\frac{1}{\sqrt{m}  \omega\lambda N})$ and $N = O(1)$ into Equation~\eqref{eq:kernel_perturbation} to get:
    \begin{align*}
        \| H_{(\nu)}'(t) - H_{(\nu)}'(0) \|_F 
        \leq & ~ O(nL^{1.5}\frac{1}{\sqrt{m}  \omega\lambda N}) \cdot \exp(O(dB)) /\delta \leq \frac{  n\mathrm{poly}( L, \exp(dB), 1/\delta) }{ \lambda \sqrt{m}}.
    \end{align*}


    Then, similar to the previous proof, we show:
    \begin{align*}
        \lambda_{\min}(H_{(\nu)}(t) \otimes I_d ) \ge \omega\lambda / 2 - \frac{ n \mathrm{poly}( L, \exp(dB), 1/\delta) }{\lambda m^{1/2}},
    \end{align*}
    and then:
    \begin{align} {\mathbb{E}}[\frac{\mathrm{d} {\cal L}(t, \mathbb{D})}{\mathrm{d} t}] \leq - \varepsilon^2 C_1(1 - \frac{C_2n}{ m^{1/2}} ) \cdot {\cal L}(t, \mathbb{D})
    \end{align}
    where $C_1 = \omega \lambda / 2$ and $C_2 =\mathrm{poly}( L, \exp(dB), 1/\delta, 1/\lambda)$.

\textbf{(i) Bound on the FFN drift.} The gradient of the loss with respect to $A_{(\nu)}$ is
    \begin{align*}
        \frac{\mathrm{d} {\cal L}(t,\mathbb{D})}{\mathrm{d} A_{(\nu)}(t)} = \sum_{p\in[nL]} \alpha_{(\nu), p}(t)\,\Big(\frac{\mathrm{d} {\cal L}(t,\mathbb{D})}{\mathrm{d} \mu_{(\nu),p}(t)}\Big)^{\!\!\top} \in \mathbb{R}^{m\times d}.
    \end{align*}
    By the matrix-product Frobenius bound $\|\sum_p u_p v_p^\top\|_F^2 \le (\sum_p \|u_p\|_2^2)(\sum_p \|v_p\|_2^2)$, Part~15 of Lemma~\ref{lem:helpful_bounds} ($\sum_p \|\mathrm{d}{\cal L}/\mathrm{d}\mu_{(\nu),p}\|_2^2 \asymp \varepsilon^2 {\cal L}(t,\mathbb{D})$) and the bound $\|\alpha_{(\nu),p}(t)\|_2 \leq O(\omega)$ established in (ii) below:
    \begin{align*}
        \Big\|\frac{\mathrm{d} {\cal L}}{\mathrm{d} A_{(\nu)}(t)}\Big\|_F^2 \leq \big(nL\cdot O(\omega^2)\big)\cdot O\big(\varepsilon^2 {\cal L}(t,\mathbb{D})\big) = O(\omega^2 nL)\cdot \varepsilon^2 {\cal L}(t,\mathbb{D}).
    \end{align*}
    By Theorem~\ref{thm:convergence}, ${\cal L}(t,\mathbb{D}) \leq \exp(-\alpha\varepsilon^2 t){\cal L}(0,\mathbb{D})$. Integrating along the gradient flow and using $\alpha = \Theta(\omega\lambda N)$, ${\cal L}(0,\mathbb{D})\leq O(Ld)$ (Part~14):
    \begin{align*}
        \|A_{(\nu)}(t) - A_{(\nu)}(0)\|_F \leq \int_0^t O(\omega\sqrt{nL})\cdot\varepsilon\sqrt{{\cal L}(s,\mathbb{D})}\,\mathrm{d} s
        \leq \frac{O(\omega\sqrt{nL\cdot Ld})}{\alpha\varepsilon} = O\Big(\frac{\sqrt{nL^2d}}{\lambda N\varepsilon}\Big).
    \end{align*}
    For this to be $\le R_A := O(1/(\sqrt m\,\omega\lambda N))$, we need $\sqrt m \le O(1/(\omega\sqrt{nL^2d}/\varepsilon))$, equivalently $m \le O(\varepsilon^2/(\omega^2 nL^2d))$; note that this is an upper bound on $m$ that we may always trade for the lower-bound condition by choosing $\varepsilon$ accordingly. Under the regime $\varepsilon = \xi/{\sf N}$ used throughout (Definition~\ref{def:factors}, Theorem~\ref{thm:scaling_law}), the strengthened width $m = \Omega\big(\frac{n^4 L^6 d^2 \exp(Cd)}{\omega^6 \lambda^8 \delta^4 N^4}\big)$ ensures the above bound is $\le R_A$. This proves (i).

Summing all complexity, we have the total complexity:
    \begin{align*}
        O(Ld^2 + L^2d+L^2+L^2d+Lmd+Lmd) \leq O(Lmd),
    \end{align*}
    where this step follows from $m$ is the major term.

    {\bf Proof of Part 2.}
    This is trivial.

From Lemma~\ref{lem:perturbations} we have (with probability at least $1-\delta$), with the $1/n$ factor from Part~15:
    \begin{align} {\mathbb{E}}\Big[\frac{\mathrm{d}}{\mathrm{d} t}{\cal L}(t,\mathbb{D})\Big] \le -\frac{C\cdot\omega\lambda N\cdot \varepsilon^2}{n}\cdot {\cal L}(t,\mathbb{D}).
    \end{align}

The instantaneous fluctuation due to stochastic batching $\mathbb{B}(t)$ is controlled as follows. For any single per-sample gradient term, Lemma~\ref{lem:helpful_bounds} (Part 15) and the perturbation control of the kernel give:
    \begin{align*}
        \Big| \frac{\mathrm{d} }{\mathrm{d} t} {\cal L}(t, \mathbb{D}) \Big| \leq O\Big(\varepsilon^2\frac{N}{\sqrt{m}}\Big) \cdot {\cal L}(t, \mathbb{D}),
    \end{align*}
    which arises from the bound $\|\frac{\mathrm{d} {\cal L}}{\mathrm{d} \mu_{(\nu)}(t)}\|^2_F\asymp \varepsilon^2 {\cal L}(t,\mathbb{D})$ summed over $N$ layers, multiplied by the kernel norm $\|H_{(\nu)}(t)\|\le O(1/\sqrt{m})$ uniformly under Definition~\ref{def:gd}. Choosing $m = \Omega(n/(N\omega\lambda)^2)$ as in Definition~\ref{def:gd}, we get:
    \begin{align*}
        \Big| \frac{\mathrm{d} }{\mathrm{d} t} {\cal L}(t, \mathbb{D}) \Big| \leq o\Big(\varepsilon^2 \frac{\sqrt{|\mathbb{B}|}}{\sqrt{n}B} \omega \lambda \Big) \cdot {\cal L}(t, \mathbb{D}),
    \end{align*}
    where $|\mathbb{B}| := \min_{t\ge 0} |\mathbb{B}(t)| \ge 1$.

By Lemma~\ref{lem:hoeffding} (Hoeffding's inequality applied to the empirical mean over a batch of size $|\mathbb{B}|$), with probability at least $1-\delta$:
    \begin{align*}
        & ~ \Big| \frac{\mathrm{d} }{\mathrm{d} t} {\cal L}(t, \mathbb{D}) - {\mathbb{E}}\big[\frac{\mathrm{d} }{\mathrm{d} t} {\cal L}(t, \mathbb{D})\big] \Big| \\
        \leq & ~  o\Big(\varepsilon^2\frac{\sqrt{|\mathbb{B}|}}{\sqrt{n}B} \omega \lambda \Big) \cdot \sqrt{\frac{n}{|\mathbb{B}|} \log(1/\delta)}\cdot {\cal L}(t, \mathbb{D}) \\
        \leq & ~  \frac{1}{2}C_1\cdot \varepsilon^2\cdot {\cal L}(t, \mathbb{D}),
    \end{align*}
    where $C_1 := C\cdot \omega\lambda N/n$, the first step uses the per-sample bound and the variance reduction from a batch of size $|\mathbb{B}|$, and the second step uses $B = O(\sqrt{\log(Nmd/\delta)})$ together with Definition~\ref{def:gd} so that the stochastic deviation is at most half of the deterministic decay. Combining with Equation~\eqref{eq:exp_decay_full}:
    \begin{align*}
        \frac{\mathrm{d} }{\mathrm{d} t} {\cal L}(t, \mathbb{D}) \leq -\frac{1}{2}C_1\cdot \varepsilon^2 \cdot {\cal L}(t, \mathbb{D}).
    \end{align*}

Solving this scalar ODE inequality (Grönwall) yields:
    \begin{align*}
        {\cal L}(t, \mathbb{D}) \leq \exp\!\left(- \frac{C\cdot \varepsilon^2  \omega\lambda Nt}{n}\right) \cdot {\cal L}(0, \mathbb{D}).
    \end{align*}

Setting $\alpha := C\cdot \omega\lambda N$ as in Theorem~\ref{thm:convergence}'s statement (we explicitly do {\it not} absorb the $1/n = 1/\mathsf{N}$ factor into the constant, because $\mathsf{N}$ is a scaling-law variable; see Remark~\ref{rem:n_in_rate}). With $t = {\sf T}$:
    \begin{align*}
        {\cal L}({\sf T}, \mathbb{D}) \leq  \exp\!\left(- \frac{\alpha \cdot \varepsilon^2  T}{\mathsf{N}}\right) \cdot {\cal L}(0, \mathbb{D}),
    \end{align*}
    as claimed. Equivalently, absorbing the $\omega N = \mathrm{poly}(1/L,1/d,1/B)$ into a polynomial-in-$(L,d,B)$ constant $\bar\alpha := C\lambda$ gives the announced informal form.

{\bf Step (a): Construct the kernel predictor.} We construct the infinite-width transformer NTK predictor as the kernel-regression solution under the layer-aggregated kernel $K(x,y) = \sum_{\nu\in[N]}H_{(\nu),x,y}(0)$ defined in Section~\ref{sub:learning_dynamics}:
    \begin{align*}
        F^{\rm ntk}(X) := \varepsilon \cdot K(\{X\},\mathbb{D}_*)\,K(\mathbb{D}_*,\mathbb{D}_*)^{-1}\,\widehat F^*(\mathbb{D}_*) + X,
    \end{align*}
    where $\mathbb{D}_*$ ranges over a dense countable subset of ${\cal X}$, $K$ is evaluated on the layer-by-layer kernel features $\{\beta_{(\nu),p}(0), \gamma_{(\nu),p}(0)\}$ from Lemma~\ref{lem:learning_dynamics}, and $\widehat F^*$ is the centred target $F^*(X) - X_\ell$ (the residual-connection adjustment, since the model output already contains the residual $X_\ell$). The centred target is:
    \begin{align*}
        \widehat F^*_\ell({\cal A}) := \begin{bmatrix}
            F^*_\ell({\cal A}_{1})^\top - {\cal A}_{1, \ell}^\top \\
            F^*_\ell({\cal A}_{2})^\top - {\cal A}_{2, \ell}^\top \\
            \vdots \\
            F^*_\ell({\cal A}_{|{\cal A}|})^\top - {\cal A}_{|{\cal A}|, \ell}^\top
        \end{bmatrix} \in \mathbb{R}^{|{\cal A}| \times d}.
    \end{align*}
    For comparison and concreteness, we record the {\it simplified prefix-MLP-only} version that suffices when $F^*$ is realizable in the simpler prefix-MLP RKHS:
    \begin{align*}
        F_{\ell}^{\rm ntk,simp}(X) := & ~  \lim_{T \to +\infty} \varepsilon \cdot {\mathbb{E}}_{w(0) \sim {\cal N}(0, I_d)}\left[ {\rm ReLU} \left( \left\langle \frac{1}{\ell} \sum_{\ell'=1}^{\ell} X_{\ell'}, w(T) \right\rangle \right) \right] + X_{\ell} \in \mathbb{R}^d \\
        = & ~ \varepsilon \cdot \Big({\cal K}_{\ell}(\{ X\}, {\cal X}) {\cal K}_{\ell}({\cal X}, {\cal X})^{-1} \widehat{F}_\ell({\cal X}) \Big)^\top,
    \end{align*}
    where ${\cal K}_\ell(\cdot,\cdot)$ is the prefix-mean ReLU NTK kernel detailed below. This simplified form uses only the standard 2-layer ReLU NTK and is what the approximation argument of \citep{adh+19} directly bounds; in the general transformer case, the Gram matrix $K$ above includes the additional $\gamma$-features from softmax-attention (Lemma~\ref{lem:learning_dynamics}, the $U_{(\nu)}$-kernel piece) that distinguish transformer NTK from a prefix-MLP NTK.
    For reference, the simplified Gram matrix is:
    \begin{align*}
        & ~ {\cal K}_{\ell, i, j}({\cal A}, {\cal B}) \\
        := & ~  \left( \frac{1}{\ell} \sum_{\ell'=1}^{\ell} {\cal A}_{i, \ell'}\right)^\top \left( \frac{1}{\ell} \sum_{\ell'=1}^{\ell} {\cal B}_{j, \ell'} \right) \cdot {\mathbb{E}}_{w \sim {\cal N}(0, I_d)}\left[\mathbb{I} \left\{\langle \frac{1}{\ell} \sum_{\ell'=1}^{\ell} {\cal A}_{i, \ell'}, w \rangle > 0,\ \langle \frac{1}{\ell} \sum_{\ell'=1}^{\ell} {\cal B}_{j, \ell'}, w \rangle > 0 \right\} \right].
    \end{align*}
    The centred target $\widehat F$ accounts for the residual connection: the model output already contains $X_\ell$, so only $F^*(X) - X_\ell$ needs to be approximated by the kernel features.

{\bf Step (c): Apply finite-width approximation.} By Theorem 3.2 in \citep{adh+19}, for any approximation target accuracy $\varepsilon_{\rm app} > 0$ (distinct from the model scaling $\varepsilon$; see Remark~\ref{rem:eps_double}), taking $m = \Theta(\mathrm{poly}(1/\varepsilon_{\rm app}))$ yields, with probability at least $1-\delta$ over $\theta(0)$:
    \begin{align*}
        \lim_{{\sf T} \rightarrow \infty}\left|F_{\ell, k}(X, \theta({\sf T})) - F_{\ell, k}^{\rm ntk}(X) \right|^2 \leq \varepsilon_{\rm app}^2 \quad \text{for all } X\in {\cal X},\, \ell\in[L],\, k\in[d].
    \end{align*}
    Summing over $\ell\in[L]$ and $k\in[d]$:
    \begin{align} \lim_{{\sf T} \to \infty} {\mathbb{E}}_{X\sim {\cal D}}\big[ \| F(X, \theta({\sf T})) - F^{\rm ntk}(X) \|_F^2 \big] \leq \varepsilon_{\rm app}^2.
    \end{align}
    Combining with Step (b) and choosing $\varepsilon_{\rm app} \lesssim {\sf M}^{-1}$ (so that the per-coordinate target accuracy of the bound from \citep{adh+19} matches the desired ${\sf M}^{-2}$ squared error after summing $Ld$ coordinates):
    \begin{align*}
        \lim_{{\sf T} \to \infty} \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} {\mathbb{E}}_{(X, Y) \sim {\cal D}}\big[ \| F(X) - F^*(X)\|_F^2 \big] \leq \varepsilon_{\rm app}^2 \leq {\sf M}^{-2},
    \end{align*}
    which is the claim. We emphasize that $\varepsilon_{\rm app}$ is a property of the function class, realized through the width $m$, and is decoupled from the model-scaling coefficient: the proof of Theorem~\ref{thm:scaling_law}, which sets the model scaling to $\varepsilon = \xi/{\sf N}$, does not invoke the specialization $\varepsilon_{\rm app} \lesssim {\sf M}^{-1}$ of this corollary, but the $\varepsilon$-parametric form of the generalization bound (see Equation~\eqref{eq:dr_bound}).

{\bf Proof of Part 1.} Following Part 5 of Lemma~\ref{lem:helpful_bounds} and Equation~\eqref{eq:F}, we have:
    \begin{align*}
        \max_{\ell \in [L], X \in {\cal X}}\| F_\ell(X) \|_2^2 \leq O(\varepsilon^2).
    \end{align*}
    We have:
    \begin{align*}
        \| F_{\ell} \|_{L^{\infty}({\cal X})} \leq & ~ \left(\max_{\ell \in [L]} \int_{\cal X} \| F_\ell(X) \|_\infty^2 \mathrm{d} X \right)^{\frac{1}{2}} \\
        \leq & ~ \left( O(\varepsilon^2) \right)^{\frac{1}{2}} \\
        \leq & ~  O(\varepsilon),
    \end{align*}
    where the first step follows from the $L^\infty$ norm, the second step follows from $\max_{\ell \in [L], X \in {\cal X}}\| F_\ell(X) \|_2^2 \leq O(\varepsilon^2)$, the last step follows from simple algebras.

{\bf Proof of Part 2.} Here, we use $R$ to denote the weight distance between arbitrary two functions $F, F' \in {\cal F}_{\sf M, N}$, following Part 3 of Lemma~\ref{lem:helpful_bounds} and some simple algebras, $R$ is bounded by $O({\sf M}B\varepsilon)$ with $\max_{F, F' \in {\cal F}_{\sf M, N}} \|F - F'\|_{L^F({\cal X})} \leq \varepsilon$, and the space of ${\cal F}_{\sf M, N}$ is an $\sf M$-dimensional ball with radius $O({\sf M}B\varepsilon)$. Thus, for any step size $\zeta > 0$, the gap is bounded by:
    \begin{align*}
        \|F - F'\|_{L^F({\cal X})} \leq \varepsilon \sqrt{Ld} \zeta \leq O(\varepsilon^2),
    \end{align*}
    where the first step follows from the definition of $F$ and Part 13 of Lemma~\ref{lem:helpful_bounds}, the second step follows from choosing $\zeta = \varepsilon$.

    We need at most $O(1)^{\sf M}$ numbers to cover this set. 
    Then we have the logarithm of the covering number:
    \begin{align*}
        V_{({\cal F}_{\sf M, N}, {\rm d})}(\zeta) \leq O(1)
    \end{align*}

Next, we bound the approximation term. Combining Corollary~\ref{cor:approximation} (with the choice $\varepsilon \lesssim {\sf M}^{-1}$) and the redefinition of ${\cal F}_{\sf M, N}(\mathbb{D})$ in Remark~\ref{rem:H1}, we have:
    \begin{align} \inf_{F' \in {\cal F}_{\sf M, N}(\mathbb{D})} \| F' - F^* \|_{L^F({\cal X})}^2 \leq {\sf M}^{-2}.
    \end{align}

{\bf Bounding the generalization (estimation) terms.} Lemma~\ref{thm:gen} requires control of two quantities: the linear-in-$\varepsilon$ term $(B_F+\xi)\varepsilon$ and the covering-entropy term $(B_F^2+\xi^2) V_{({\cal F}_{\sf M, N}(\mathbb{D}),{\rm d})}(\varepsilon)/{\sf N}$. We bound them in turn.
    \begin{align} (B_F+\xi)\varepsilon \leq (\varepsilon + \xi)\varepsilon = \varepsilon^2 + \xi\varepsilon \leq O(\xi\varepsilon),
    \end{align}
    where the inequality uses $B_F \leq O(\varepsilon)$ from Part 1 of Lemma~\ref{lem:generalization_helper} and the dominance $\varepsilon^2 \leq \xi\varepsilon$ for the regime $\varepsilon \leq \xi$ that follows from the choice $\varepsilon = \Theta(1/{\sf M})$ with $\xi$ being a fixed noise level.

    Similarly,
    \begin{align} \frac{(B_F^2+\xi^2)V_{({\cal F}_{\sf M, N}(\mathbb{D}), {\rm d})}(\varepsilon)}{\sf N}
        \leq O\left(\frac{\varepsilon^2+\xi^2}{\sf N}\right) \leq O\left(\frac{\xi^2}{\sf N}\right),
    \end{align}
    where the first step combines Part 1 ($B_F^2\leq O(\varepsilon^2)$) and Part 2 ($V \leq O(1)$) of Lemma~\ref{lem:generalization_helper}, and the second step uses $\varepsilon^2 \leq \xi^2$ in the regime considered.

{\bf Combining the bounds.} Plugging Equation~\eqref{eq:approx_term}, Equation~\eqref{eq:bf_xi_eps}, and Equation~\eqref{eq:cov_term} into Lemma~\ref{thm:gen} yields:
    \begin{align*}
        \| F - F^* \|_{L^F({\cal X})}^2
        \leq & ~ 4 \inf_{F' \in {\cal F}_{\sf M, N}(\mathbb{D})} \| F' - F^* \|_{L^F({\cal X})}^2 + Ld \cdot O\!\left(\frac{\xi^2}{\sf N} + \xi\varepsilon\right) \\
        \leq & ~ 4 {\sf M}^{-2} + Ld \cdot O\!\left(\frac{\xi^2}{\sf N} + \frac{\xi}{\sf M}\right) \\
        \leq & ~ \big(4 {\sf M}^{-1} + Ld\cdot\xi\big) \cdot {\sf M}^{-1} + \frac{Ld\cdot \xi^2}{\sf N},
    \end{align*}
    where the second step uses $\varepsilon = \Theta({\sf M}^{-1})$ and the third step regroups summands. We retain $L$ and $d$ explicitly in both terms because they are scaling-law variables independent of $\xi$ (sequence length and embedding dimension, not noise scale). Combining with Equation~\eqref{eq:bound_delta_R} and taking the infimum over $F\in {\cal F}_{\sf M, N}(\mathbb{D})$ and the supremum over the data distribution, we obtain:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}} \Delta{\cal R}(F) \leq \big(4{\sf M}^{-1} + Ld\cdot \xi\big) \cdot {\sf M}^{-1} + \frac{Ld \cdot\xi^2}{\sf N}.
    \end{align*}
    This completes the proof.

Let $F = F(\cdot, \theta({\sf T}))$ denote the optimizing function obtained from running gradient flow until time $\sf T$, i.e. $F \in {\cal F}_{\sf M, T, N}(\mathbb{D})$ in the sense of Definition~\ref{def:gd}. Let $F' \in {\cal F}_{\sf M, N}(\mathbb{D})$ be the empirical risk minimizer over the (re-defined; see Remark~\ref{rem:H1}) parameter space. By the triangle inequality in $L^F({\cal X})$ norm:
    \begin{align*}
        \Delta {\cal R}(F) \leq & ~ \| F - F^*\|_{L^F({\cal X})}^2 \\
        \leq & ~ \left(\| F - F'\|_{L^F({\cal X})} + \| F' - F^*\|_{L^F({\cal X})}\right)^2,
    \end{align*}
    where the first step follows from Equation~\eqref{eq:bound_delta_R}, the second step follows from the triangle inequality.

Following Part 12 of Lemma~\ref{lem:helpful_bounds} (which transforms parameter-space distance into the $L^F({\cal X})$ functional distance) and the definition of $F$, we get:
    \begin{align*}
        \| F - F'\|_{L^F({\cal X})} \leq & ~ \min\Big\{ P\exp\Big(-\frac{\alpha \varepsilon^2 \mathsf{T}}{2\mathsf{N}}\Big),\, O(1) \Big\} \cdot \sqrt{{\cal L}(0, \mathbb{D})} \leq \exp\Big(-\frac{\alpha \varepsilon^2 \mathsf{T}}{4\mathsf{N}}\Big) \cdot \sqrt{{\cal L}(0, \mathbb{D})}, \qquad P := \frac{2CL\mathsf{N}}{\alpha\varepsilon},
    \end{align*}
    with the following bookkeeping. The $O(1)\cdot\sqrt{{\cal L}(0,\mathbb{D})}$ branch of the minimum is the crude bound: every $F$ in the Good Model Class keeps its hidden states and outputs at the initialization scale (Parts~3 and~5 of Lemma~\ref{lem:helpful_bounds}), so $\|F-F'\|_{L^F({\cal X})} = O(\sqrt{Ld}) = O(\sqrt{{\cal L}(0,\mathbb{D})})$, the latter since ${\cal L}(0,\mathbb{D}) = \Omega(Ld)$ with high probability over the noise. The second inequality absorbs the polynomial prefactor $P = \mathrm{poly}(\mathsf{N}, L, d, 1/\xi, 1/\lambda, 1/\omega)$ into the exponent: for $\alpha\varepsilon^2{\sf T}/(2\mathsf{N}) \ge 2\log P$ this is the standard absorption $P e^{-x} \le e^{-x/2}$; for smaller $\sf T$ --- a burn-in window of the same order as the Stage-I/II boundary, up to the $O(1)$ factor $\log P/\log({\sf N}Ld/\xi^2)$ --- the displayed exponential is read together with the crude branch, i.e.\ the upper-bound prefactor of Theorem~\ref{thm:scaling_law} absorbs $P$ inside the burn-in window, where the bound asserts no more than $\Delta{\cal R}(F) = O({\cal L}(0,\mathbb{D}))$. We rename $\alpha/4$ as $\alpha$ below.

We square both sides of the previous bound to obtain a bound on $\Delta{\cal R}(F)$ itself:
    \begin{align} \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)
        \leq & ~  2\exp\!\left(-2\alpha \varepsilon^2 \mathsf{T}/\mathsf{N}\right) \cdot {\cal L}(0, \mathbb{D}) + O\Big(\frac{\xi^2}{{\sf N}} + \xi\varepsilon\Big),
    \end{align}
    using $(a+b)^2 \le 2a^2 + 2b^2$ and absorbing the constant $2$ into the $O(\cdot)$ on the second summand; the $1/\mathsf{N}$ in the exponent is the average-loss factor of Remark~\ref{rem:n_in_rate}. For any total computational resource ${\sf C}$ with dataset size ${\sf N}$, we follow Definition~\ref{def:gd} to require ${\sf M} = \Theta({\sf N}^3)$, and we choose $\varepsilon = \xi/{\sf N}$. Substituting:
    \begin{align*}
        \xi\varepsilon = \xi^2/{\sf N} \quad \text{and} \quad \alpha \varepsilon^2/\mathsf{N} = \alpha \xi^2/{\sf N}^3.
    \end{align*}

{\it Condition 1 (Compute-Starved Stage).} When the optimization term $\exp(-2\alpha\varepsilon^2 \mathsf{T}/\mathsf{N})$ dominates the statistical $\xi^2/\mathsf{N}$ term, equivalently when:
    \begin{align*}
        & ~ {\sf T} \le \frac{\mathsf{N}\log({\sf N}\cdot Ld /\xi^2)}{2\alpha\varepsilon^2}
        = \frac{{\sf N}^3 \log({\sf N}\cdot Ld /\xi^2)}{2\alpha \xi^2},
    \end{align*}
    which using ${\sf C} = O({\sf MTN})$ and ${\sf M} = {\sf N}^3$ translates into:
    \begin{align*}
        {\sf C} \leq \frac{{\sf N}^7\log( {\sf N}  \cdot Ld/\xi^2)}{\xi^2}\quad \text{up to constants},
    \end{align*}
    we have:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F) \leq & ~ C \exp\!\left(-\alpha \xi^2{\sf T}/{\sf N}^3\right) \cdot {\cal L}(0, \mathbb{D}) \\
        = & ~  C \exp\Big(-\alpha \xi^2 \frac{{\sf MTN}}{{\sf N}^4{\sf M}}\Big) \cdot {\cal L}(0, \mathbb{D}) \\
        \leq & ~  C \exp\Big(-\alpha \xi^2 \frac{{\sf C}}{{\sf N}^4{\sf M}}\Big) \cdot {\cal L}(0, \mathbb{D}) \\
        \leq & ~ C \exp\Big(-\alpha \xi^2 \frac{{\sf C}}{{\sf N}^7}\Big) \cdot {\cal L}(0, \mathbb{D}),
    \end{align*}
    where the second equality multiplies and divides by ${\sf MN}$, the third inequality uses ${\sf C} = O({\sf MTN}) \geq {\sf NTM}/c$ for some constant $c$, and the fourth uses ${\sf M} \le {\sf N}^3$ in the exponent. The constant $C = \mathrm{poly}(L, d, 1/\lambda, 1/\omega)$.

{\it Condition 2 (Data-Limited Stage).} When ${\sf T} > {\sf N}^3 \log({\sf N}\cdot Ld /\xi^2)/(2\alpha\xi^2)$, or equivalently:
    \begin{align*}
        {\sf C} = O({\sf MTN}) > \frac{{\sf M}{\sf N}^4\log( {\sf N}  \cdot Ld/\xi^2)}{\xi^2}
        \iff {\sf C} > \frac{{\sf N}^7\log( {\sf N}  \cdot Ld/\xi^2)}{\xi^2},
    \end{align*}
    the optimization term decays faster than the statistical floor; the bound \eqref{eq:dr_bound} reduces to:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq & ~ O\Big(\frac{\xi^2}{{\sf N}} \Big).
    \end{align*}

    We now optimize over ${\sf N}$ subject to the compute budget. The constraint is $\xi^{-2}\,{\sf N}^7\log({\sf N}\cdot Ld/\xi^2) \le {\sf C}$. Writing $u := {\sf N}^7/\xi^2$, this becomes:
    \begin{align*}
        u\log(u^{1/7} \cdot \xi^{2/7} Ld) \leq {\sf C},
    \end{align*}
    whose maximal solution satisfies (treating the slowly varying log factor via the Lambert $W$ function $W(\cdot)$, which inverts $z\mapsto z\log z$):
    \begin{align*}
        u_{\max} = O\Big( \frac{{\sf C}}{W({\sf C}/\xi^{12})}\Big),
        \quad\text{so}\quad
        {\sf N}_{\max} = O\Big( \frac{{\sf C}\xi^2}{W({\sf C}/\xi^{12})} \Big)^{1/7}.
    \end{align*}
    Substituting back:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq & ~ O\Big(\frac{\xi^2}{{\sf N}_{\max}} \Big) = \xi^{12/7} \cdot O\left( \frac{{\sf C}}{W({\sf C}/\xi^{12})} \right)^{-1/7} \leq \xi^{12/7} \cdot \widetilde{O}\left( {\sf C} \right)^{-1/7},
    \end{align*}
    where $W(\cdot)$ is the Lambert $W$ function and $\widetilde O$ hides $\log {\sf C}$ factors. The exponent $-1/7$ is a direct consequence of the $1/\mathsf{N}$ factor in Theorem~\ref{thm:convergence}.

{\it Condition 2 (Data-Limited Stage).} When ${\sf T} > {\sf N}^3 \log({\sf N}\cdot Ld /\xi^2)/(2\alpha\xi^2)$, or equivalently:
    \begin{align*}
        {\sf C} = O({\sf MTN}) > \frac{{\sf M}{\sf N}^4\log( {\sf N}  \cdot Ld/\xi^2)}{\xi^2}
        \iff {\sf C} > \frac{{\sf N}^7\log( {\sf N}  \cdot Ld/\xi^2)}{\xi^2},
    \end{align*}
    the optimization term decays faster than the statistical floor; the bound \eqref{eq:dr_bound} reduces to:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq & ~ O\Big(\frac{\xi^2}{{\sf N}} \Big).
    \end{align*}

We now optimize over ${\sf N}$ subject to the compute budget. The constraint is $\xi^{-2}\,{\sf N}^7\log({\sf N}\cdot Ld/\xi^2) \le {\sf C}$. Writing $u := {\sf N}^7/\xi^2$, this becomes:
    \begin{align*}
        u\log(u^{1/7} \cdot \xi^{2/7} Ld) \leq {\sf C},
    \end{align*}
    whose maximal solution satisfies (treating the slowly varying log factor via the Lambert $W$ function $W(\cdot)$, which inverts $z\mapsto z\log z$):
    \begin{align*}
        u_{\max} = O\Big( \frac{{\sf C}}{W({\sf C}/\xi^{12})}\Big),
        \quad\text{so}\quad
        {\sf N}_{\max} = O\Big( \frac{{\sf C}\xi^2}{W({\sf C}/\xi^{12})} \Big)^{1/7}.
    \end{align*}
    Substituting back:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq & ~ O\Big(\frac{\xi^2}{{\sf N}_{\max}} \Big) = \xi^{12/7} \cdot O\left( \frac{{\sf C}}{W({\sf C}/\xi^{12})} \right)^{-1/7} \leq \xi^{12/7} \cdot \widetilde{O}\left( {\sf C} \right)^{-1/7},
    \end{align*}
    where $W(\cdot)$ is the Lambert $W$ function and $\widetilde O$ hides $\log {\sf C}$ factors. The exponent $-1/7$ is a direct consequence of the $1/\mathsf{N}$ factor in Theorem~\ref{thm:convergence}.

\textbf{Step 1: Two-point construction.} Let $g\in {\cal H}_K$ be the non-zero element fixed by hypothesis, normalized so that $\|g\|_{L^F({\cal X})}=1$. Define the two-point family:
    \begin{align*}
        F_0^* := 0, \qquad F_1^* := \rho \cdot g, \qquad \rho := \sqrt{\frac{\xi^2}{2{\sf N}}}.
    \end{align*}
    Both lie in ${\cal H}_K$.

\textbf{Step 2: Bound the KL divergence.} Under each $F_j^*$, the data law is $\mathcal{D}_j = {\cal X}\times \mathcal{N}(F_j^*(X), \xi^2 I_{Ld})$, so the per-sample KL divergence is
    \begin{align*}
        D_{\rm KL}({\cal D}_0\|{\cal D}_1) = {\mathbb{E}}_X\Big[\frac{1}{2\xi^2}\|F_0^*(X) - F_1^*(X)\|_F^2\Big] = \frac{\rho^2}{2\xi^2} \cdot \|g\|_{L^F({\cal X})}^2 = \frac{\rho^2}{2\xi^2}.
    \end{align*}
    For an i.i.d.\ dataset of size $\sf N$, $D_{\rm KL}({\cal D}_0^{\otimes {\sf N}}\|{\cal D}_1^{\otimes {\sf N}}) = {\sf N}\cdot \rho^2/(2\xi^2)$. With our choice $\rho^2 = \xi^2/(2{\sf N})$, we have:
    \begin{align*}
        D_{\rm KL}({\cal D}_0^{\otimes {\sf N}}\|{\cal D}_1^{\otimes {\sf N}}) = \frac{1}{4} \le \log 2.
    \end{align*}

\textbf{Step 3: Apply Le Cam's two-point lemma} (Theorem 2.2 of \citealp{tsy09}). For any estimator $\widehat F$:
    \begin{align*}
        \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}_{\mathbb{D}\sim {\cal D}_j^{\otimes{\sf N}}}\big[\|\widehat F-F_j^*\|_{L^F({\cal X})}^2\big] \ge \frac{1}{4}\big(1-\sqrt{D_{\rm KL}/2}\big)\cdot \|F_0^*-F_1^*\|_{L^F({\cal X})}^2.
    \end{align*}
    Substituting the bound on KL:
    \begin{align*}
        \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}\big[\|\widehat F-F_j^*\|_{L^F({\cal X})}^2\big] \ge \frac{1}{4}\big(1 - \sqrt{1/8}\big)\cdot \rho^2 \ge \frac{1}{8}\cdot \frac{\xi^2}{2{\sf N}} = \frac{\xi^2}{16{\sf N}}.
    \end{align*}

\textbf{Step 4: Translate to excess risk.} By Equation~\eqref{eq:bound_delta_R}, $\Delta{\cal R}(F) = \|F - F^*\|_{L^F({\cal X})}^2$, so:
    \begin{align*}
        \inf_{\widehat F}\sup_{F^*\in{\cal H}_K} {\mathbb{E}}\big[\Delta{\cal R}(\widehat F)\big] \ge \inf_{\widehat F}\sup_{j\in\{0,1\}} {\mathbb{E}}\big[\Delta{\cal R}(\widehat F)\big] \ge \frac{\xi^2}{16{\sf N}},
    \end{align*}
    yielding the claim with $c_1 = 1/16$.

\textbf{Step 1: Reduction to a quadratic problem.} By Lemma~\ref{lem:perturbations} and Definition~\ref{def:gd}, the loss in the lazy regime is well approximated by its second-order expansion around $\theta(0)$:
    \begin{align*}
        {\cal L}(t,\mathbb{D}) = \frac{1}{2}\Delta\theta(t)^\top {\sf H} \Delta\theta(t) + \langle b, \Delta\theta(t)\rangle + {\cal L}(0, \mathbb{D}) + o(1),
    \end{align*}
    where $\Delta\theta(t) := \theta(t)-\theta(0)$, ${\sf H}$ is the parameter-space Hessian assembled from $\{H_{(\nu)}(0)\otimes I_d\}_{\nu\in[N]}$, and $b$ is the residual gradient. The $o(1)$ correction is uniform on the lazy-training ball by Part~9--10 of Lemma~\ref{lem:helpful_bounds}. Thus the optimization problem reduces (up to higher-order terms) to minimizing a quadratic with eigenvalue spread $[\omega\lambda/2,\;\omega\lambda_{\max}]$.

\textbf{Step 2: Apply Nemirovski--Yudin.} For any first-order method on a strongly convex quadratic with condition number $\kappa = \lambda_{\max}/\lambda_{\min}$, there exist initial conditions for which the loss after $T$ gradient queries satisfies (Theorem~2.1.13 of \citealp{nes03}; see also \citealp{ny83}):
    \begin{align*}
        {\cal L}(T) - {\cal L}^* \ge \Big(\frac{\sqrt{\kappa}-1}{\sqrt{\kappa}+1}\Big)^{2T} \cdot ({\cal L}(0)-{\cal L}^*).
    \end{align*}
    Translating to the gradient-flow setting requires a continuous-time limit. The standard reduction takes step size $\eta = 1/\lambda_{\max}$ and substitutes $T \to t/\eta = t\lambda_{\max}$:
    \begin{align*}
        \log\Big(\frac{\sqrt\kappa - 1}{\sqrt\kappa + 1}\Big)^{2T} = -2T \log\frac{\sqrt\kappa+1}{\sqrt\kappa - 1} \approx -\frac{4T}{\sqrt\kappa}
    \end{align*}
    for $\kappa\to\infty$. Substituting $T\to t\lambda_{\max}$ gives an exponential decay of rate $4\lambda_{\max}/\sqrt\kappa = 4\sqrt{\lambda_{\min}\lambda_{\max}}$. As $\eta\to 0$ (continuous limit), the bound is preserved (it is step-size monotone in this regime), giving:
    \begin{align*}
        {\cal L}(t) - {\cal L}^* \ge \exp\Big(-4\sqrt{\lambda_{\min}\lambda_{\max}}\cdot t\Big)\cdot ({\cal L}(0)-{\cal L}^*).
    \end{align*}
    Since $\lambda_{\min}\ge \omega\lambda/2$ (Lemma~\ref{lem:perturbations}) and $\lambda_{\max}\le \omega\lambda_{\max}^{(K)}$ where $\lambda_{\max}^{(K)} := \max_\nu \lambda_{\max}(H_{(\nu)}'(0)/\omega)$:
    \begin{align*}
        {\cal L}(t) \ge \exp\big(-C_{\rm opt}\cdot \omega\sqrt{\lambda \lambda_{\max}^{(K)}}\cdot t\big)\cdot {\cal L}(0).
    \end{align*}
    The geometric mean $\sqrt{\lambda\lambda_{\max}^{(K)}}$ is {\it not} a single constant: it differs from $\lambda$ by a factor of $\sqrt{\kappa}=\sqrt{\lambda_{\max}^{(K)}/\lambda}$, which is $\mathrm{poly}(L,d,1/\delta)^{1/2}$ rather than $O(1)$. We therefore retain $\sqrt{\kappa}$ explicitly in the exponent (this is the unavoidable Nemirovski--Yudin condition-number gap; see Appendix~\ref{app_sub:matching_precise}). Including the $\varepsilon^2$ factor that arises when reading the loss in $L^F({\cal X})$ rather than parameter space (Part~15 of Lemma~\ref{lem:helpful_bounds}, with the $1/n$ factor) and the $1/n$ from the average-loss normalization:
    \begin{align*}
        {\cal L}({\sf T}, \mathbb{D}) \ge c_2\cdot \exp\!\left(-\frac{C_{\rm opt}\cdot \sqrt{\kappa}\,\omega\lambda N\cdot \varepsilon^2 \cdot {\sf T}}{n}\right)\cdot {\cal L}(0, \mathbb{D}).
    \end{align*}

\textbf{Step 3: Translate to compute.} Using ${\sf C} = O({\sf MTN})$, ${\sf M}=\Theta({\sf N}^3)$ (Definition~\ref{def:gd}) and $\varepsilon = \xi/{\sf N}$ (the choice that defines the data-limited boundary in Theorem~\ref{thm:scaling_law}), and absorbing $\omega N\lambda$ into the constant $\mathrm{poly}(L,d,B,\lambda)$:
    \begin{align*}
        \frac{\sqrt{\kappa}\,\omega\lambda N\varepsilon^2 {\sf T}}{n} = \sqrt{\kappa}\,\omega\lambda N\cdot \frac{\xi^2}{{\sf N}^2}\cdot \frac{{\sf C}}{{\sf MN}\cdot \mathsf{N}} = \frac{\sqrt{\kappa}\,\omega\lambda N\xi^2 {\sf C}}{{\sf N}^4 \cdot {\sf M}\cdot \mathsf{N}} \le \Theta\Big(\frac{\sqrt{\kappa}\,\xi^2 {\sf C}}{{\sf N}^7}\Big),
    \end{align*}
    which yields:
    \begin{align*}
        \inf_{F\in {\cal F}_{\sf M, T, N}(\mathbb{D})}\sup_{\mathbb{D}\in{\cal D}}\Delta{\cal R}(F) \ge c_2'\cdot \exp\!\left(-C_{\rm opt}'\,\sqrt{\kappa}\,\xi^2{\sf C}/{\sf N}^7\right)\cdot {\cal L}(0,\mathbb{D}).
    \end{align*}
    The conversion from training-loss lower bound to excess-risk lower bound uses the standard fact that $\Delta {\cal R}(F)\ge \|F-F^*\|_{L^F({\cal X})}^2 - O(\xi^2/{\sf N})$ (cf.~Equation~\eqref{eq:bound_delta_R}), and the second term is dominated by the exponential in the Compute-Starved Stage where Equation~\eqref{eq:cond_C} fails.

{\bf Proof of Time-Law.} Under fixed ${\sf N}$ and ${\sf M} = \Omega({\sf N}^3)$, set $\varepsilon = \xi/{\sf N}$. Substituting into Equation~\eqref{eq:dr_bound} (whose optimization term is $\exp(-2\alpha\varepsilon^2{\sf T}/\mathsf{N})\cdot{\cal L}(0,\mathbb{D})$, with the $1/\mathsf{N}$ factor from Remark~\ref{rem:n_in_rate}) gives the bound directly:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)
        \leq O\!\left(\exp(-\alpha\,\xi^2\,{\sf T}/{\sf N}^3)\right) + O\Big(\frac{\xi^2}{\sf N}\Big),
    \end{align*}
    so this proof reduces to {\it Condition 1} of Theorem~\ref{thm:scaling_law} with ${\sf C} = {\sf MTN}$, ${\sf M}, {\sf N}$ fixed.

{\bf Proof of Model-Law.} Given $\zeta \in (0, 1/3]$, choose $\varepsilon = \xi/{\sf M}^\zeta$. Following {\it Condition 2} of Theorem~\ref{thm:scaling_law}, choose
    \begin{align*}
        {\sf T} = \frac{{\sf M}^{2\zeta}\,\mathsf{N}\,\log({\sf N}\cdot Ld/\xi^2)}{\xi^2},
    \end{align*}
    so $\alpha\varepsilon^2 {\sf T}/\mathsf{N} = \alpha\log({\sf N}\cdot Ld/\xi^2)$, hence $\exp(-\alpha\varepsilon^2 {\sf T}/\mathsf{N}) = ({\sf N}\cdot Ld/\xi^2)^{-\alpha}$. For this to be $\leq \xi^2 {\sf M}^{-\zeta}$, we need $\alpha\log({\sf N}\cdot Ld/\xi^2) \ge \zeta\log\mathsf{M} - 2\log\xi$, equivalently $\alpha \ge (\zeta\log\mathsf{M}-2\log\xi)/\log(\mathsf{N}\cdot Ld/\xi^2)$. This is feasible whenever $\mathsf{M}\le \mathsf{N}^{1/\zeta}$ (so $\zeta\log\mathsf{M}\le \log\mathsf{N}$), i.e.\ in the regime stated in the theorem; we therefore restrict the Model-Law to ${\sf M}\le{\sf N}^{1/\zeta}$. Then:
    \begin{align*}
        {\sf C} = O({\sf MTN}) = \frac{{\sf M}^{2\zeta+1}{\sf N}^2\log({\sf N}\cdot Ld/\xi^2)}{\xi^2}
        \leq \frac{{\sf M}^{2\zeta + 5/3}\log({\sf N}\cdot Ld/\xi^2)}{\xi^2},
    \end{align*}
    where the inequality uses ${\sf N} \leq {\sf M}^{1/3}$ (since ${\sf M} \geq {\sf N}^3$).

    The Model-Law regime is the part of parameter space where the bound from $\xi\varepsilon$ dominates over $\xi^2/{\sf N}$, i.e.~$\xi^2/{\sf N} \leq \xi\varepsilon = \xi^2/{\sf M}^\zeta$, which holds when ${\sf M}^\zeta \leq {\sf N}$, i.e.~${\sf M} \leq {\sf N}^{1/\zeta}$. Combined with ${\sf M} \geq {\sf N}^3$ and the feasibility condition above, this gives the regime ${\sf N}^3 \leq {\sf M} \leq {\sf N}^{1/\zeta}$ stated in the theorem. In this regime:
    \begin{align*}
        \inf_{F \in {\cal F}_{\sf M, T, N}(\mathbb{D})} \sup_{\mathbb{D} \in {\cal D}}  \Delta{\cal R}(F)  \leq \xi^2 {\sf M}^{-\zeta},
    \end{align*}
    as claimed.
